from taf.cloud.lcmaas.schemas.schema_base import SchemaObject, SchemaField


class CNFInstantiatedHelmRelease(SchemaObject):
    release_name = SchemaField(name="name")
    helm_chart = SchemaField(name="chart")
    release_version = SchemaField(name="version")
    release_status = SchemaField(name="status")
    release_ns = SchemaField(name="namespace")
    override_values = SchemaField(name="override_values")

    def __init__(self, release_name, helm_chart, release_version, release_status, release_ns, override_values):
        self.release_name = release_name
        self.helm_chart = helm_chart
        self.release_version = release_version
        self.release_status = release_status
        self.release_ns = release_ns
        self.override_values = override_values

        super(CNFInstantiatedHelmRelease, self).__init__()


class Overrides(SchemaObject):
    chart = SchemaField(name='chart', optional=True)
    override_value = SchemaField(name='override_value', optional=True)

    def __init__(self, chart, override_value):
        self.chart = chart
        self.override_value = override_value

        super(Overrides, self).__init__()


class CNFInstanceInfo(SchemaObject):
    cnf_instance_name = SchemaField(name='name')
    vi_name = SchemaField(name='vi')
    prepare_releases = SchemaField(name='prepare_releases', klass=CNFInstantiatedHelmRelease, many=True, optional=True)
    main_release = SchemaField(name='main_release', klass=CNFInstantiatedHelmRelease, optional=True)
    overrides = SchemaField(name='overrides', klass=Overrides, many=True, not_null=True)
    cnf_package = SchemaField(name='cnf_package')

    def __init__(self, cnf_instance_name, vi_name, prepare_releases, main_release, overrides, cnf_package):
        self.cnf_instance_name = cnf_instance_name
        self.vi_name = vi_name
        self.prepare_releases = prepare_releases
        self.main_release = main_release
        self.overrides = overrides
        self.cnf_package = cnf_package

        super(CNFInstanceInfo, self).__init__()


class DppInfoV1(SchemaObject):
    dpp_name = SchemaField(name="name", not_null=True)
    dpp_ns = SchemaField(name='namespace')
    dpp_group = SchemaField(name="group")
    dpp_status = SchemaField(name="status", not_null=True)
    dpp_process = SchemaField(name="process")
    cnf_package = SchemaField(name="cnf_package")
    cnf_instance = SchemaField(name="cnf_instance", klass=CNFInstanceInfo)

    def __init__(self, dpp_name, dpp_ns, dpp_group, dpp_status, dpp_process, cnf_package, cnf_instance):
        self.dpp_name = dpp_name
        self.dpp_ns = dpp_ns
        self.dpp_group = dpp_group
        self.dpp_status = dpp_status
        self.dpp_process = dpp_process
        self.cnf_package = cnf_package
        self.cnf_instance = cnf_instance

        super(DppInfoV1, self).__init__()
